begin;
create table public.users(id uuid primary key references auth.users(id) on delete cascade, display_name text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create function public.new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.users(id) values(new.id) on conflict do nothing; return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.new_user();
insert into public.users(id) select id from auth.users on conflict do nothing;
create table public.projects(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,title text not null check(length(title)>0),description text not null default '',due_date date,status text not null default 'todo' check(status in ('todo','doing','done','hold')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(), unique(id,user_id));
create table public.goals(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,project_id uuid,parent_id uuid,period text not null default 'long' check(period in ('long','month','week')),title text not null,description text not null default '',kpi text not null default '',target numeric not null default 100 check(target>0),actual numeric not null default 0,owner text not null default '',start_date date,due_date date,status text not null default 'todo' check(status in ('todo','doing','done','hold')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,user_id),foreign key(project_id,user_id) references public.projects(id,user_id),foreign key(parent_id,user_id) references public.goals(id,user_id));
create table public.tasks(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,title text not null check(length(title)>0),description text not null default '',project_id uuid,goal_id uuid,start_date date,due_date date,importance int not null default 3 check(importance between 1 and 5),urgency int not null default 3 check(urgency between 1 and 5),estimated_minutes int not null default 30 check(estimated_minutes>=0),actual_minutes int not null default 0 check(actual_minutes>=0),status text not null default 'todo' check(status in ('todo','doing','done','hold')),manual_priority int check(manual_priority between 0 and 3),notes text not null default '',position double precision not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,user_id),foreign key(project_id,user_id) references public.projects(id,user_id),foreign key(goal_id,user_id) references public.goals(id,user_id),check(start_date is null or due_date is null or start_date<=due_date));
create table public.task_dependencies(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,task_id uuid not null,depends_on uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(task_id,user_id) references public.tasks(id,user_id) on delete cascade,foreign key(depends_on,user_id) references public.tasks(id,user_id) on delete cascade,unique(task_id,depends_on),check(task_id<>depends_on));
create table public.schedules(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,title text not null,task_id uuid,starts_at timestamptz not null,ends_at timestamptz not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(task_id,user_id) references public.tasks(id,user_id) on delete cascade,check(ends_at>starts_at));
create table public.recordings(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,title text not null,storage_path text not null,duration_seconds int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,user_id));
create table public.transcripts(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,recording_id uuid,content text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(recording_id,user_id) references public.recordings(id,user_id) on delete cascade);
create table public.meeting_notes(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,project_id uuid,title text not null,transcript text not null default '',summary text not null default '',action_items jsonb not null default '[]',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,user_id),foreign key(project_id,user_id) references public.projects(id,user_id));
create table public.action_items(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,meeting_id uuid not null,task_id uuid,title text not null,owner text,due_date date,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(meeting_id,user_id) references public.meeting_notes(id,user_id) on delete cascade,foreign key(task_id,user_id) references public.tasks(id,user_id));
create table public.ai_recommendations(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,task_id uuid,priority int check(priority between 0 and 3),reason text not null,source text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(task_id,user_id) references public.tasks(id,user_id) on delete cascade);
create table public.activity_logs(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,action text not null,entity_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.integration_connections(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,provider text not null,status text not null default 'disconnected',last_synced_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.notification_preferences(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,enabled boolean not null default false,minutes_before int not null default 15,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id));
create function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now();return new;end $$;
do $$ declare t text;begin foreach t in array array['projects','goals','tasks','task_dependencies','schedules','recordings','transcripts','meeting_notes','action_items','ai_recommendations','activity_logs','integration_connections','notification_preferences'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('create policy own_rows on public.%I for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id)',t);
 execute format('create index on public.%I(user_id)',t);
 execute format('create trigger touch_updated before update on public.%I for each row execute function public.touch_updated_at()',t);
 end loop;end $$;
alter table public.users enable row level security;
create policy own_user on public.users for select to authenticated using(auth.uid()=id);
create policy update_user on public.users for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
create function public.log_task_change() returns trigger language plpgsql security invoker set search_path=public as $$ begin insert into public.activity_logs(user_id,action,entity_id) values(coalesce(new.user_id,old.user_id),'task.'||lower(TG_OP),coalesce(new.id,old.id));return coalesce(new,old);end $$;
create trigger task_audit after insert or update or delete on public.tasks for each row execute function public.log_task_change();
alter publication supabase_realtime add table public.tasks, public.projects, public.goals, public.schedules, public.meeting_notes, public.activity_logs;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('recordings','recordings',false,26214400,array['audio/webm','audio/mp4','audio/mpeg','audio/wav','audio/ogg','audio/x-m4a']) on conflict(id) do nothing;
create policy private_recordings_select on storage.objects for select to authenticated using(bucket_id='recordings' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy private_recordings_insert on storage.objects for insert to authenticated with check(bucket_id='recordings' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy private_recordings_delete on storage.objects for delete to authenticated using(bucket_id='recordings' and (storage.foldername(name))[1]=(select auth.uid())::text);
commit;
